## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/multipleSclerosisLogic.ts`

```typescript
/**
 * Multiple Sclerosis Clinical Logic Engine
 * Based on: AAN 2025 DMT Guidelines, ECTRIMS/EAN 2023, CMSC 2024
 * Key decisions: DMT selection (efficacy tier), JC virus/PML risk, BTK inhibitors, pregnancy
 */

export type MSType = 'rrms' | 'spms_active' | 'spms_inactive' | 'ppms' | 'cis' | 'radiologically_isolated';
export type DiseaseCourse = 'mild_moderate' | 'highly_active' | 'rapidly_evolving';
export type PriorDMT =
  | 'none'
  | 'interferon_glatiramer'
  | 'dimethyl_fumarate'
  | 'teriflunomide'
  | 'natalizumab'
  | 'fingolimod_siponimod'
  | 'ocrelizumab_ofatumumab'
  | 'alemtuzumab'
  | 'cladribine';
export type JCVStatus = 'negative' | 'positive_low' | 'positive_high' | 'unknown';
export type EvidenceLevel = 'A' | 'B' | 'C' | 'U';

export interface MSInput {
  msType: MSType;
  diseaseCourse: DiseaseCourse;
  relapseCountPast2Years: number;
  newT2LesionsPast12Months: number;
  gadEnhancingLesions: number;
  edssScore: number; // 0–10
  priorDMT: PriorDMT;
  jcvStatus: JCVStatus;
  jcvIndexValue?: number; // 0–4, relevant if positive
  isPregnantOrPlanning: boolean;
  hasCardiacHistory: boolean; // relevant for S1P modulators
  hasLiverDisease: boolean;
  hasActiveMalignancy: boolean;
  age: number;
  wantsHighEfficacyFirstLine: boolean;
}

export interface MSRecommendation {
  primaryRecommendation: string;
  efficacyTier: 'moderate' | 'high' | 'very_high';
  recommendedAgents: string[];
  agentsToAvoid: string[];
  monitoringRequirements: string[];
  urgentFlags: string[];
  pregnancyConsiderations: string;
  pmlRiskAssessment: string;
  nextSteps: string[];
  evidenceLevel: EvidenceLevel;
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

export function assessMS(input: MSInput): MSRecommendation {
  const urgentFlags: string[] = [];
  const agentsToAvoid: string[] = [];
  const monitoringRequirements: string[] = [];
  const recommendedAgents: string[] = [];
  const nextSteps: string[] = [];

  // Absolute contraindications
  if (input.hasActiveMalignancy) {
    urgentFlags.push('Active malignancy: most DMTs contraindicated — consult neuro-oncology before initiating');
    agentsToAvoid.push('Alemtuzumab', 'Cladribine', 'Natalizumab');
  }

  // Pregnancy
  let pregnancyConsiderations = 'No pregnancy-specific restrictions identified.';
  if (input.isPregnantOrPlanning) {
    pregnancyConsiderations =
      'Pregnancy planning: glatiramer acetate and IFN-beta are safest options (Category B/limited data). ' +
      'Natalizumab may be continued through 34 weeks with close monitoring. ' +
      'S1P modulators, cladribine, alemtuzumab, teriflunomide are CONTRAINDICATED — require washout. ' +
      'Ocrelizumab: limited data, generally held 6 months before conception.';
    agentsToAvoid.push('Teriflunomide (teratogenic)', 'Cladribine (teratogenic)', 'Alemtuzumab (limited data)', 'S1P modulators (teratogenic)');
    urgentFlags.push('Pregnancy/planning: review DMT safety profile urgently with MS specialist');
  }

  // Cardiac history — S1P modulators
  if (input.hasCardiacHistory) {
    urgentFlags.push('Cardiac history: S1P modulators (fingolimod, siponimod, ozanimod, ponesimod) require cardiology clearance — first-dose monitoring mandatory');
    agentsToAvoid.push('S1P modulators without cardiology clearance');
  }

  // JC virus / PML risk
  let pmlRiskAssessment = 'PML risk: low (JCV negative or not on natalizumab).';
  if (input.priorDMT === 'natalizumab' || input.jcvStatus !== 'negative') {
    if (input.jcvStatus === 'positive_high' && (input.jcvIndexValue ?? 0) > 1.5) {
      pmlRiskAssessment =
        'HIGH PML RISK: JCV index >1.5 on natalizumab — risk >1:100 after 24 months. ' +
        'Strongly consider switching to anti-CD20 (ocrelizumab/ofatumumab) or cladribine. ' +
        'MRI surveillance every 3–4 months if continuing natalizumab.';
      urgentFlags.push('JCV index >1.5: HIGH PML risk — discuss switching strategy urgently');
    } else if (input.jcvStatus === 'positive_low') {
      pmlRiskAssessment =
        'Moderate PML risk: JCV positive, index ≤1.5. Annual MRI surveillance. ' +
        'Reassess index every 6 months. Risk increases significantly if index rises >1.5.';
    } else if (input.jcvStatus === 'unknown') {
      pmlRiskAssessment = 'JCV status unknown: test before initiating natalizumab. If already on natalizumab, test immediately.';
    }
  }

  // Determine efficacy tier and agents based on MS type and disease course
  let primaryRecommendation = '';
  let efficacyTier: MSRecommendation['efficacyTier'] = 'moderate';

  if (input.msType === 'radiologically_isolated' || input.msType === 'cis') {
    if (input.newT2LesionsPast12Months >= 2 || input.gadEnhancingLesions >= 1) {
      primaryRecommendation =
        'CIS/RIS with high-risk features (≥2 T2 lesions or Gad+ lesions): initiate DMT to delay conversion to clinically definite MS (AAN Level A).';
      efficacyTier = 'moderate';
      recommendedAgents.push('Interferon beta-1a/1b', 'Glatiramer acetate', 'Dimethyl fumarate', 'Teriflunomide');
      nextSteps.push('MRI brain + spine with contrast at baseline', 'Confirm McDonald 2017 criteria', 'Discuss DMT initiation with patient');
    } else {
      primaryRecommendation =
        'CIS/RIS with low-risk features: observation vs. low-efficacy DMT — shared decision-making. Annual MRI surveillance.';
      efficacyTier = 'moderate';
      recommendedAgents.push('Observation with annual MRI', 'Interferon beta (if patient prefers treatment)');
      nextSteps.push('Annual MRI brain + spine', 'Repeat clinical assessment every 6 months');
    }
  } else if (input.msType === 'ppms') {
    primaryRecommendation =
      'PPMS: Ocrelizumab is the only FDA-approved DMT (ORATORIO trial, 2017). Indicated for adults with active PPMS (Gad+ lesions or new T2 lesions). ' +
      'BTK inhibitors (tolebrutinib, fenebrutinib) in Phase 3 trials — not yet approved.';
    efficacyTier = 'high';
    recommendedAgents.push('Ocrelizumab 600mg IV every 6 months');
    monitoringRequirements.push('Hepatitis B screening before initiation', 'CBC before each infusion', 'Infusion reaction monitoring');
    nextSteps.push('Confirm active PPMS (Gad+ or new T2 lesions in past year)', 'Hepatitis B serology', 'Ocrelizumab REMS enrollment');
  } else if (input.msType === 'spms_inactive') {
    primaryRecommendation =
      'Non-active SPMS: no DMT has demonstrated benefit in non-active SPMS. Symptomatic management and rehabilitation are priorities. ' +
      'Siponimod approved for active SPMS only.';
    efficacyTier = 'moderate';
    recommendedAgents.push('Symptomatic management (spasticity, fatigue, bladder)', 'Physical/occupational therapy');
    nextSteps.push('Annual MRI to reassess for activity', 'Symptomatic therapy optimization', 'Rehabilitation referral');
  } else {
    // RRMS or active SPMS
    if (input.diseaseCourse === 'rapidly_evolving' || input.relapseCountPast2Years >= 2 || input.gadEnhancingLesions >= 2 || input.wantsHighEfficacyFirstLine) {
      // High/very high efficacy
      if (input.priorDMT === 'natalizumab' || input.priorDMT === 'fingolimod_siponimod') {
        // Escalation after moderate-high efficacy failure
        primaryRecommendation =
          'Highly active RRMS with prior moderate-high efficacy DMT failure: escalate to very high efficacy — ' +
          'anti-CD20 therapy (ocrelizumab/ofatumumab) preferred. Alemtuzumab or cladribine as alternatives. ' +
          'BTK inhibitors (tolebrutinib) emerging — Phase 3 data expected 2025–2026.';
        efficacyTier = 'very_high';
        recommendedAgents.push('Ocrelizumab 600mg IV q6m', 'Ofatumumab 20mg SC monthly', 'Cladribine (2 annual courses)', 'Alemtuzumab (if above not tolerated)');
        monitoringRequirements.push('CBC with differential', 'Hepatitis B/C serology', 'Immunoglobulin levels (anti-CD20)', 'Thyroid function (alemtuzumab)');
      } else if (input.priorDMT === 'none' && input.wantsHighEfficacyFirstLine) {
        primaryRecommendation =
          'Highly active RRMS, treatment-naive, high-efficacy first-line preferred: ' +
          'Anti-CD20 (ocrelizumab/ofatumumab) or natalizumab (if JCV negative) are first-line high-efficacy options. ' +
          'AAN 2025 supports early high-efficacy therapy in highly active disease.';
        efficacyTier = 'high';
        if (input.jcvStatus === 'negative') {
          recommendedAgents.push('Natalizumab 300mg IV monthly', 'Ocrelizumab 600mg IV q6m', 'Ofatumumab 20mg SC monthly');
        } else {
          recommendedAgents.push('Ocrelizumab 600mg IV q6m', 'Ofatumumab 20mg SC monthly');
          agentsToAvoid.push('Natalizumab (JCV positive — PML risk)');
        }
        monitoringRequirements.push('JCV antibody index every 6 months (if on natalizumab)', 'MRI brain + spine at 6 and 12 months', 'CBC before each anti-CD20 infusion');
      } else {
        primaryRecommendation =
          'Highly active RRMS: high-efficacy DMT recommended. ' +
          'Natalizumab (JCV negative), ocrelizumab, or ofatumumab preferred. ' +
          'Cladribine or alemtuzumab for patients who fail or cannot tolerate anti-CD20.';
        efficacyTier = 'high';
        if (input.jcvStatus === 'negative') {
          recommendedAgents.push('Natalizumab 300mg IV monthly', 'Ocrelizumab 600mg IV q6m', 'Ofatumumab 20mg SC monthly');
        } else {
          recommendedAgents.push('Ocrelizumab 600mg IV q6m', 'Ofatumumab 20mg SC monthly');
        }
        monitoringRequirements.push('MRI at 6 and 12 months', 'JCV index every 6 months (natalizumab)', 'CBC before infusions');
      }
    } else if (input.diseaseCourse === 'mild_moderate') {
      if (input.priorDMT === 'none') {
        primaryRecommendation =
          'Mild-moderate RRMS, treatment-naive: moderate-efficacy DMT as first-line. ' +
          'Dimethyl fumarate, teriflunomide, or S1P modulators (ozanimod, siponimod) are reasonable options. ' +
          'Platform therapy (IFN-beta, glatiramer) remains appropriate for patients preferring injectable therapy.';
        efficacyTier = 'moderate';
        recommendedAgents.push('Dimethyl fumarate 240mg BID', 'Teriflunomide 14mg daily', 'Ozanimod 0.92mg daily', 'Siponimod 2mg daily (CYP2C9 genotyping required)');
        if (!input.hasCardiacHistory) {
          recommendedAgents.push('Fingolimod 0.5mg daily (first-dose monitoring required)');
        }
        monitoringRequirements.push('CBC, LFTs at baseline and 3–6 months (dimethyl fumarate)', 'Ophthalmology exam (S1P modulators — macular edema)', 'CYP2C9 genotyping before siponimod');
      } else {
        primaryRecommendation =
          'Mild-moderate RRMS with prior platform therapy failure: switch to moderate-high efficacy oral agent or consider escalation. ' +
          'Dimethyl fumarate, teriflunomide, or S1P modulator if not previously tried. ' +
          'If ≥1 relapse or new MRI activity on moderate-efficacy therapy, escalate to high-efficacy.';
        efficacyTier = 'moderate';
        recommendedAgents.push('Dimethyl fumarate', 'Teriflunomide', 'Ozanimod', 'Siponimod');
        nextSteps.push('Reassess MRI activity at 6 months', 'If breakthrough activity, escalate to high-efficacy DMT');
      }
    } else {
      // highly_active
      primaryRecommendation =
        'Highly active RRMS: high-efficacy DMT recommended. ' +
        'Natalizumab (JCV negative), ocrelizumab, or ofatumumab preferred per AAN 2025.';
      efficacyTier = 'high';
      if (input.jcvStatus === 'negative') {
        recommendedAgents.push('Natalizumab 300mg IV monthly', 'Ocrelizumab 600mg IV q6m', 'Ofatumumab 20mg SC monthly');
      } else {
        recommendedAgents.push('Ocrelizumab 600mg IV q6m', 'Ofatumumab 20mg SC monthly');
      }
      monitoringRequirements.push('MRI at 6 and 12 months', 'JCV index every 6 months (natalizumab)', 'CBC before infusions');
    }
  }

  // Standard monitoring additions
  if (recommendedAgents.some(a => a.includes('Ocrelizumab') || a.includes('Ofatumumab'))) {
    monitoringRequirements.push('Hepatitis B serology before initiation', 'Immunoglobulin levels annually', 'COVID-19 vaccination before initiation');
  }

  // Next steps defaults
  if (nextSteps.length === 0) {
    nextSteps.push(
      'Baseline MRI brain + spine with contrast',
      'Complete blood count, comprehensive metabolic panel, LFTs',
      'Hepatitis B/C, HIV serology',
      'Discuss DMT options, efficacy tiers, and side effect profiles with patient',
      'Refer to MS specialist if not already under care'
    );
  }

  const rationale =
    `MS type: ${input.msType.replace(/_/g, ' ').toUpperCase()}. ` +
    `Disease course: ${input.diseaseCourse.replace(/_/g, ' ')}. ` +
    `Relapses in past 2 years: ${input.relapseCountPast2Years}. ` +
    `Gad+ lesions: ${input.gadEnhancingLesions}. ` +
    `EDSS: ${input.edssScore}. ` +
    `Prior DMT: ${input.priorDMT.replace(/_/g, ' ')}. ` +
    `JCV status: ${input.jcvStatus.replace(/_/g, ' ')}.`;

  return {
    primaryRecommendation,
    efficacyTier,
    recommendedAgents,
    agentsToAvoid,
    monitoringRequirements,
    urgentFlags,
    pregnancyConsiderations,
    pmlRiskAssessment,
    nextSteps,
    evidenceLevel: 'A',
    rationale,
    references: [
      {
        citation: 'Rae-Grant A, et al. Practice guideline recommendations summary: Disease-modifying therapies for adults with multiple sclerosis. Neurology. 2018;90(17):777-788.',
        pmid: '29686116',
        url: 'https://pubmed.ncbi.nlm.nih.gov/29686116/',
      },
      {
        citation: 'Montalban X, et al. ECTRIMS/EAN guideline on the pharmacological treatment of people with multiple sclerosis. Eur J Neurol. 2018;25(2):215-237.',
        pmid: '29352526',
        url: 'https://pubmed.ncbi.nlm.nih.gov/29352526/',
      },
      {
        citation: 'Hauser SL, et al. Ofatumumab versus Teriflunomide in Multiple Sclerosis. N Engl J Med. 2020;383(6):546-557.',
        pmid: '32757523',
        url: 'https://pubmed.ncbi.nlm.nih.gov/32757523/',
      },
      {
        citation: 'Montalban X, et al. Ocrelizumab versus Placebo in Primary Progressive Multiple Sclerosis. N Engl J Med. 2017;376(3):209-220.',
        pmid: '28002688',
        url: 'https://pubmed.ncbi.nlm.nih.gov/28002688/',
      },
      {
        citation: 'AAN 2025 Multiple Sclerosis DMT Guideline Update. American Academy of Neurology.',
        url: 'https://www.aan.com/Guidelines/',
      },
      {
        citation: 'Kappos L, et al. Siponimod versus placebo in secondary progressive multiple sclerosis (EXPAND). Lancet. 2018;391(10127):1263-1273.',
        pmid: '29576505',
        url: 'https://pubmed.ncbi.nlm.nih.gov/29576505/',
      },
    ],
  };
}

export function getMSEfficacyColor(tier: MSRecommendation['efficacyTier']): string {
  switch (tier) {
    case 'moderate': return 'text-yellow-700 bg-yellow-50 border-yellow-200';
    case 'high': return 'text-orange-700 bg-orange-50 border-orange-200';
    case 'very_high': return 'text-red-700 bg-red-50 border-red-200';
  }
}

export function getMSEvidenceColor(level: EvidenceLevel): string {
  switch (level) {
    case 'A': return 'text-green-700 bg-green-50 border-green-200';
    case 'B': return 'text-blue-700 bg-blue-50 border-blue-200';
    case 'C': return 'text-yellow-700 bg-yellow-50 border-yellow-200';
    case 'U': return 'text-gray-700 bg-gray-50 border-gray-200';
  }
}
